/// `https://api.sylphx.com`.
pub const DEFAULT_BASE_URL: &str = "https://api.sylphx.com";

#[cfg(feature = "http")]
impl HttpTransport {
    pub fn builder() -> HttpTransportBuilder {
        HttpTransportBuilder::default()
    }

    /// `SYLPHX_API_KEY` (required), `SYLPHX_BASE_URL`, `SYLPHX_API_VERSION`.
    pub fn from_env() -> Result<Self, Error> {
        let key = std::env::var("SYLPHX_API_KEY")
            .ok()
            .filter(|k| !k.is_empty())
            .ok_or_else(|| Error::InvalidArgument("SYLPHX_API_KEY is not set".into()))?;
        let mut b = Self::builder().api_key(key);
        if let Some(url) = std::env::var("SYLPHX_BASE_URL")
            .ok()
            .filter(|u| !u.is_empty())
        {
            b = b.base_url(url);
        }
        if let Some(v) = std::env::var("SYLPHX_API_VERSION")
            .ok()
            .filter(|v| !v.is_empty())
        {
            b = b.api_version(v);
        }
        b.build()
    }

    /// The base URL requests go to.
    pub fn base_url(&self) -> &str {
        &self.base_url
    }

    async fn send_once(
        &self,
        request: &HttpRequest,
        idempotency_key: Option<&str>,
        deadline: Option<std::time::Instant>,
    ) -> Result<(HttpResponse, Option<std::time::Duration>), Error> {
        let method = reqwest::Method::from_bytes(request.method.as_bytes())
            .map_err(|e| Error::InvalidArgument(e.to_string()))?;
        let mut rb = self
            .http
            .request(method, format!("{}{}", self.base_url, request.path))
            .header(reqwest::header::ACCEPT, "application/json");
        if !request.query.is_empty() {
            rb = rb.query(&request.query);
        }
        if let Some(key) = &self.api_key {
            rb = rb.bearer_auth(key);
        }
        if let Some(v) = &self.api_version {
            rb = rb.header("Sylphx-Version", v);
        }
        if let Some(k) = idempotency_key {
            rb = rb.header("Idempotency-Key", k);
        }
        if let Some(deadline) = deadline {
            let left = deadline.saturating_duration_since(std::time::Instant::now());
            if left.is_zero() {
                return Err(Error::Transport(
                    "deadline exceeded before the request was sent".into(),
                ));
            }
            rb = rb
                .timeout(left)
                .header("Sylphx-Request-Timeout", left.as_millis().to_string());
        }
        if let Some(body) = &request.body {
            rb = rb.json(body);
        }
        let response = rb
            .send()
            .await
            .map_err(|e| Error::Transport(e.to_string()))?;
        let status = response.status().as_u16();
        let header = |name: &str| {
            response
                .headers()
                .get(name)
                .and_then(|v| v.to_str().ok())
                .map(str::to_string)
        };
        let request_id = header("sylphx-request-id");
        let retry_after = header("retry-after")
            .and_then(|v| v.trim().parse::<u64>().ok())
            .map(std::time::Duration::from_secs);
        let body = response
            .bytes()
            .await
            .map_err(|e| Error::Transport(e.to_string()))?
            .to_vec();
        Ok((
            HttpResponse {
                status,
                request_id,
                body,
            },
            retry_after,
        ))
    }
}

#[cfg(feature = "http")]
impl Transport for HttpTransport {
    async fn send(&self, request: HttpRequest) -> Result<HttpResponse, Error> {
        // One key per logical call, reused across its retries (§3.6).
        let key = request.mutation.then(|| uuid::Uuid::now_v7().to_string());
        let deadline = self.timeout.map(|t| std::time::Instant::now() + t);
        let mut attempt = 0u32;
        loop {
            let result = self.send_once(&request, key.as_deref(), deadline).await;
            let retry_after = match &result {
                Ok((r, after)) if retryable_status(r) => *after,
                // A GET, or a mutation that carries an idempotency key, is
                // safe to resend after a transport failure.
                Err(Error::Transport(_)) => None,
                _ => return result.map(|(r, _)| r),
            };
            if attempt >= self.max_retries {
                return result.map(|(r, _)| r);
            }
            let wait = retry_after.unwrap_or_else(|| backoff(attempt));
            if deadline.is_some_and(|d| std::time::Instant::now() + wait >= d) {
                return result.map(|(r, _)| r);
            }
            tokio::time::sleep(wait).await;
            attempt += 1;
        }
    }
}

/// Whether an answer may be retried: 429, 502, 503, 504, or a problem body
/// with `retryable: true` (§3.8).
#[cfg(feature = "http")]
fn retryable_status(r: &HttpResponse) -> bool {
    match r.status {
        429 | 502 | 503 | 504 => true,
        s if s >= 400 => serde_json::from_slice::<serde_json::Value>(&r.body)
            .ok()
            .and_then(|v| v.get("retryable").and_then(|b| b.as_bool()))
            .unwrap_or(false),
        _ => false,
    }
}

/// Exponential backoff with full jitter: uniform in [0, min(8s, 250ms·2^n)].
#[cfg(feature = "http")]
fn backoff(attempt: u32) -> std::time::Duration {
    let cap = 250u64.saturating_mul(1 << attempt.min(5)).min(8_000);
    std::time::Duration::from_millis(fastrand::u64(0..=cap))
}
